#!/usr/bin/env bash
# Selected-peer Russian IPv4 bypass; no customer data is embedded in this file.
set -Eeuo pipefail
umask 077
if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
  cat <<'HELP'
Run as root on an existing AWG relay created by this repository, after restoring LucX DB.
Install and enable: bash ru-bypass.sh install --clients 'NAME1,NAME2,NAME3'
If --clients is omitted, names are read from /dev/tty.
Disable: ru-bypass off       Enable again: ru-bypass on       Check: ru-bypass status
Also supported: bash ru-bypass.sh off|on|status
Only selected IPv4 peers, IP-only bypass. No domain/DNS changes or boot persistence.
HELP
  exit 0
fi
[[ "$(uname -s)" == Linux && "$EUID" -eq 0 ]] || { echo 'Run as root on the Linux relay.' >&2; exit 1; }
for dependency in python3 nft ip awg systemctl curl; do
  command -v "$dependency" >/dev/null || { echo "Missing $dependency. Restore the AWG relay infrastructure first." >&2; exit 1; }
done
PYTHONDONTWRITEBYTECODE=1 /usr/bin/python3 - "$@" <<'RU_BYPASS_PYTHON'
FILES={'ru_bypass_common.py': '"""Narrow, runtime-only country bypass for explicitly selected AWG peers."""\nimport hashlib\nimport json\nimport subprocess\nfrom pathlib import Path\n\nTARGETS=json.loads((Path(__file__).resolve().parent/\'config.json\').read_text())[\'targets\']\nUNSELECTED=next(\'10.8.0.\'+str(n) for n in range(2,255) if \'10.8.0.\'+str(n) not in TARGETS.values())\nTABLE=\'awg_ru3_trial\'\nROUTE_TABLE=\'51833\'\nMARK=\'0x52000000\'\nMASK=\'0xff000000\'\nSOURCE=\'10.8.0.0/24\'\nPREFIX=\'awg-ru3-trial:\'\nPRIORITIES=(10021,10022)\n\ndef output(*args):\n    return subprocess.check_output(args,text=True)\n\ndef rule_signature(rule):\n    value=json.loads(json.dumps(rule))\n    for expr in value.get(\'expr\',[]):\n        if \'counter\' in expr:expr[\'counter\']={}\n    return value\n\ndef rules(document):\n    return [item[\'rule\'] for item in document[\'nftables\'] if \'rule\' in item]\n\ndef anchor(document):\n    candidates=[]\n    for rule in rules(document):\n        if rule.get(\'chain\')!=\'forward_guard\':continue\n        for expr in rule[\'expr\']:\n            match=expr.get(\'match\',{})\n            if match.get(\'op\')==\'!=\' and match.get(\'right\')==\'awg32\' and match.get(\'left\')=={\'meta\':{\'key\':\'oifname\'}}:\n                candidates.append(rule[\'handle\'])\n    assert len(candidates)==1,\'Cannot identify the existing fail-closed forwarding guard\'\n    return candidates[0]\n\ndef nft_config(cidrs,wan,position):\n    addresses=\', \'.join(sorted(TARGETS.values()))\n    networks=\', \'.join(cidrs)\n    text=f\'\'\'table inet {TABLE} {{\n set peers4 {{ type ipv4_addr; elements = {{ {addresses} }}; }}\n set ru4 {{ type ipv4_addr; flags interval; auto-merge; elements = {{ {networks} }}; }}\n chain classify {{\n  type filter hook prerouting priority mangle; policy accept;\n  iifname "xui-awg1" ip saddr @peers4 ct mark & {MASK} == {MARK} counter meta mark set (meta mark & 0x00ffffff) | {MARK} return comment "{PREFIX}restore"\n\'\'\'\n    for name,ip in sorted(TARGETS.items()):\n        text+=f\'  iifname "xui-awg1" ip saddr {ip} ct state new ip daddr @ru4 counter ct mark set (ct mark & 0x00ffffff) | {MARK} meta mark set (meta mark & 0x00ffffff) | {MARK} comment "{PREFIX}{name}"\\n\'\n    text+=f\'\'\' }}\n chain postrouting_direct {{\n  type nat hook postrouting priority srcnat - 2; policy accept;\n  oifname "{wan}" ip saddr @peers4 ct mark & {MASK} == {MARK} counter masquerade comment "{PREFIX}snat"\n }}\n}}\ninsert rule inet amnezia_legacy_relay forward_guard position {position} iifname "xui-awg1" oifname "{wan}" ip saddr {{ {addresses} }} ct mark & {MASK} == {MARK} ct state {{ new, established, related }} counter accept comment "{PREFIX}allow-out"\ninsert rule inet amnezia_legacy_relay forward_guard position {position} iifname "{wan}" oifname "xui-awg1" ip daddr {{ {addresses} }} ct mark & {MASK} == {MARK} ct state {{ established, related }} counter accept comment "{PREFIX}allow-return"\n\'\'\'\n    return text\n\ndef routing_commands(wan,gateway):\n    return [\n        [\'ip\',\'-4\',\'route\',\'add\',\'table\',ROUTE_TABLE,gateway+\'/32\',\'dev\',wan,\'scope\',\'link\'],\n        [\'ip\',\'-4\',\'route\',\'add\',\'table\',ROUTE_TABLE,\'default\',\'via\',gateway,\'dev\',wan],\n        [\'ip\',\'-4\',\'rule\',\'add\',\'priority\',str(PRIORITIES[0]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'table\',ROUTE_TABLE],\n        [\'ip\',\'-4\',\'rule\',\'add\',\'priority\',str(PRIORITIES[1]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'unreachable\'],\n    ]\n\ndef cleanup_commands(wan,gateway):\n    return [\n        [\'ip\',\'-4\',\'rule\',\'del\',\'priority\',str(PRIORITIES[0]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'table\',ROUTE_TABLE],\n        [\'ip\',\'-4\',\'rule\',\'del\',\'priority\',str(PRIORITIES[1]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'unreachable\'],\n        [\'ip\',\'-4\',\'route\',\'del\',\'table\',ROUTE_TABLE,\'default\',\'via\',gateway,\'dev\',wan],\n        [\'ip\',\'-4\',\'route\',\'del\',\'table\',ROUTE_TABLE,gateway+\'/32\',\'dev\',wan,\'scope\',\'link\'],\n    ]\n\ndef nft_cleanup(document,table_exists):\n    commands=[f\'delete rule inet amnezia_legacy_relay forward_guard handle {r["handle"]}\'\n              for r in rules(document) if r.get(\'comment\',\'\').startswith(PREFIX)]\n    if table_exists:commands.append(f\'delete table inet {TABLE}\')\n    return \'\\n\'.join(commands)+\'\\n\' if commands else \'\'\n', 'simulate.py': '"""Exercise the exact nft/PBR/NAT rules in disposable namespaces, not production."""\nimport ipaddress,json,os,subprocess,sys,time,uuid\nfrom pathlib import Path\nfrom ru_bypass_common import UNSELECTED,TARGETS,TABLE,MARK,ROUTE_TABLE,anchor,nft_config,routing_commands,cleanup_commands,nft_cleanup\n\nroot=Path(sys.argv[1]).resolve()\nsource=json.loads((root/\'ru-ipv4.json\').read_text())\ntag=\'rub\'+uuid.uuid4().hex[:7]\nnames={role:tag+role for role in [\'r\',\'c\',\'w\',\'f\']}\ncreated=[];links=[];servers=[]\ndef run(args,check=True):\n    result=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)\n    if check and result.returncode:\n        detail=\'\\n\'.join(line[:350] for line in result.stderr.splitlines()[:15])\n        raise RuntimeError(\'Namespace command failed: \'+\' \'.join(args[:7])+\'\\n\'+detail)\n    return result\ndef ns(role,*args,check=True):return run([\'ip\',\'netns\',\'exec\',names[role],*args],check=check)\ndef link(a,b,iface_a,iface_b,number):\n    left=tag+\'a\'+str(number);right=tag+\'b\'+str(number)\n    run([\'ip\',\'link\',\'add\',left,\'type\',\'veth\',\'peer\',\'name\',right]);links.append(left)\n    run([\'ip\',\'link\',\'set\',left,\'netns\',names[a]])\n    run([\'ip\',\'link\',\'set\',right,\'netns\',names[b]])\n    ns(a,\'ip\',\'link\',\'set\',left,\'name\',iface_a);ns(b,\'ip\',\'link\',\'set\',right,\'name\',iface_b)\n    ns(a,\'ip\',\'link\',\'set\',iface_a,\'up\');ns(b,\'ip\',\'link\',\'set\',iface_b,\'up\')\ndef nft(role,text,name):\n    path=root/name;path.write_text(text)\n    ns(role,\'nft\',\'-c\',\'-f\',str(path));ns(role,\'nft\',\'-f\',str(path))\ntry:\n    existing=run([\'ip\',\'netns\',\'list\']).stdout\n    for name in names.values():\n        assert name not in existing\n        run([\'ip\',\'netns\',\'add\',name]);created.append(name)\n    for role in names:ns(role,\'ip\',\'link\',\'set\',\'lo\',\'up\')\n    link(\'r\',\'c\',\'xui-awg1\',\'client0\',1)\n    link(\'r\',\'w\',\'ens3\',\'sink0\',2)\n    link(\'r\',\'f\',\'awg32\',\'sink0\',3)\n    for role,interface,address in [(\'r\',\'xui-awg1\',\'10.8.0.1/24\'),(\'r\',\'ens3\',\'192.0.2.1/24\'),\n          (\'w\',\'sink0\',\'192.0.2.2/24\'),(\'r\',\'awg32\',\'10.203.32.2/30\'),(\'f\',\'sink0\',\'10.203.32.1/30\')]:\n        ns(role,\'ip\',\'address\',\'add\',address,\'dev\',interface)\n    for ip in [*TARGETS.values(),UNSELECTED]:ns(\'c\',\'ip\',\'address\',\'add\',ip+\'/24\',\'dev\',\'client0\')\n    ns(\'c\',\'ip\',\'route\',\'add\',\'default\',\'via\',\'10.8.0.1\')\n    ns(\'r\',\'sysctl\',\'-q\',\'-w\',\'net.ipv4.ip_forward=1\',\'net.ipv4.conf.all.rp_filter=0\',\'net.ipv4.conf.default.rp_filter=0\')\n    for iface in [\'ens3\',\'awg32\',\'xui-awg1\']:ns(\'r\',\'sysctl\',\'-q\',\'-w\',f\'net.ipv4.conf.{iface}.rp_filter=0\')\n    ns(\'r\',\'ip\',\'route\',\'add\',\'default\',\'via\',\'192.0.2.2\')\n    ns(\'r\',\'ip\',\'route\',\'add\',\'table\',\'51832\',\'default\',\'dev\',\'awg32\')\n    ns(\'r\',\'ip\',\'rule\',\'add\',\'priority\',\'10031\',\'from\',\'10.8.0.0/24\',\'table\',\'51832\')\n    ns(\'r\',\'ip\',\'rule\',\'add\',\'priority\',\'10032\',\'from\',\'10.8.0.0/24\',\'unreachable\')\n    base=\'\'\'table inet amnezia_legacy_relay {\n chain forward_guard {\n  type filter hook forward priority -10; policy accept;\n  iifname "xui-awg1" ip saddr != 10.8.0.0/24 drop\n  iifname "xui-awg1" ip daddr { 10.0.0.0/8, 127.0.0.0/8, 192.168.0.0/16 } drop\n  iifname "xui-awg1" oifname != "awg32" drop\n  oifname "xui-awg1" iifname != "awg32" drop\n  oifname "xui-awg1" ct state != { established, related } drop\n }\n chain old_nat { type nat hook postrouting priority srcnat - 1; policy accept;\n  ip saddr 10.8.0.0/24 oifname "awg32" snat ip to 10.203.32.2\n }\n}\n\'\'\'\n    nft(\'r\',base,\'sim-base.nft\')\n    for role,path_label in [(\'w\',\'relay-wan\'),(\'f\',\'foreign-exit\')]:\n        for ip in [\'77.88.55.80\',\'1.1.1.1\']:ns(role,\'ip\',\'address\',\'add\',ip+\'/32\',\'dev\',\'lo\')\n        code="from http.server import BaseHTTPRequestHandler,HTTPServer\\nimport json\\nclass H(BaseHTTPRequestHandler):\\n def do_GET(self):\\n  body=json.dumps({\'path\':"+repr(path_label)+",\'source_ip\':self.client_address[0]}).encode();self.send_response(200);self.end_headers();self.wfile.write(body)\\n def log_message(self,*args):pass\\nHTTPServer((\'0.0.0.0\',18080),H).serve_forever()"\n        servers.append(subprocess.Popen([\'ip\',\'netns\',\'exec\',names[role],\'python3\',\'-u\',\'-c\',code],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL))\n    time.sleep(.3)\n    guard=json.loads(ns(\'r\',\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\').stdout)\n    config=nft_config(source[\'ipv4_cidrs\'],\'ens3\',anchor(guard))\n    nft(\'r\',config,\'sim-trial.nft\')\n    for command in routing_commands(\'ens3\',\'192.0.2.2\'):ns(\'r\',*command)\n    records=[]\n    def request(ip,destination,expected):\n        response=ns(\'c\',\'curl\',\'--noproxy\',\'*\',\'--interface\',ip,\'-fsS\',\'--connect-timeout\',\'2\',\'--max-time\',\'3\',f\'http://{destination}:18080\')\n        result=json.loads(response.stdout)\n        assert result[\'path\']==expected,(ip,destination,result)\n        assert result[\'source_ip\']==(\'192.0.2.1\' if expected==\'relay-wan\' else \'10.203.32.2\'),result\n        records.append({\'source\':ip,\'destination\':destination,\'path\':result[\'path\'],\'snat\':result[\'source_ip\']})\n    for ip in [*TARGETS.values(),UNSELECTED]:\n        request(ip,\'77.88.55.80\',\'relay-wan\' if ip in TARGETS.values() else \'foreign-exit\')\n        request(ip,\'1.1.1.1\',\'foreign-exit\')\n    ns(\'r\',\'ip\',\'route\',\'del\',\'table\',ROUTE_TABLE,\'default\',\'via\',\'192.0.2.2\',\'dev\',\'ens3\')\n    failed=ns(\'c\',\'curl\',\'--noproxy\',\'*\',\'--interface\',next(iter(TARGETS.values())),\'-fsS\',\'--max-time\',\'2\',\'http://77.88.55.80:18080\',check=False)\n    assert failed.returncode!=0,\'Marked route must fail closed if its table is unavailable\'\n    ns(\'r\',\'ip\',\'route\',\'add\',\'table\',ROUTE_TABLE,\'default\',\'via\',\'192.0.2.2\',\'dev\',\'ens3\')\n    guard=json.loads(ns(\'r\',\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\').stdout)\n    nft(\'r\',nft_cleanup(guard,True),\'sim-rollback.nft\')\n    for command in cleanup_commands(\'ens3\',\'192.0.2.2\'):ns(\'r\',*command)\n    for ip in [*TARGETS.values(),UNSELECTED]:\n        request(ip,\'77.88.55.80\',\'foreign-exit\')\n        request(ip,\'1.1.1.1\',\'foreign-exit\')\n    report={\'namespace_tests\':len(records),\'selected_peer_count\':len(TARGETS),\'selected_peers_ru_direct\':True,\'other_peer_ru_foreign\':True,\n        \'non_ru_foreign_for_all\':True,\'snat_verified\':True,\'fail_closed_verified\':True,\'rollback_verified\':True,\n        \'production_network_untouched\':True,\'records\':records}\n    (root/\'simulation-report.json\').write_text(json.dumps(report,indent=2))\n    print(json.dumps({k:v for k,v in report.items() if k!=\'records\'}),flush=True)\nfinally:\n    for process in servers:\n        process.terminate()\n        try:process.wait(timeout=2)\n        except subprocess.TimeoutExpired:process.kill();process.wait()\n    for name in reversed(created):run([\'ip\',\'netns\',\'del\',name],check=False)\n    for name in links:run([\'ip\',\'link\',\'del\',name],check=False)\n', 'apply.py': '"""Apply a tested, bounded IP-only bypass to selected peers; no service restart or customer writes."""\nimport hashlib,ipaddress,json,os,re,sqlite3,subprocess,sys,time\nfrom datetime import datetime,timezone,timedelta\nfrom pathlib import Path\nfrom ru_bypass_common import *\n\nos.umask(0o077)\nroot=Path(__file__).resolve().parent\nsource=json.loads((root/\'ru-ipv4.json\').read_text())\nsimulation=json.loads((root/\'simulation-report.json\').read_text())\nassert simulation[\'namespace_tests\']==4*(len(TARGETS)+1) and all(simulation.get(key) for key in [\'selected_peers_ru_direct\',\'other_peer_ru_foreign\',\'non_ru_foreign_for_all\',\'snat_verified\',\'fail_closed_verified\',\'rollback_verified\'])\nassert not (root/\'state.json\').exists(),\'This trial was already attempted; inspect state before repeating.\'\nnetworks=[ipaddress.ip_network(value) for value in source[\'ipv4_cidrs\']]\nassert all(network.version==4 and network.is_global and network.prefixlen>=8 for network in networks)\ndef is_ru(ip):return any(ipaddress.ip_address(ip) in network for network in networks)\nassert is_ru(\'77.88.55.80\') and not is_ru(\'1.1.1.1\')\ndef command(args,check=True):\n    result=subprocess.run(args,capture_output=True,text=True)\n    if check and result.returncode:\n        (root/\'last-command-error.txt\').write_text(\' \'.join(args)+\'\\n\'+result.stdout+result.stderr)\n        raise RuntimeError(\'Trial command failed; see private last-command-error.txt\')\n    return result\ndef customer_hash():\n    with sqlite3.connect(\'file:/etc/x-ui/x-ui.db?mode=ro\',uri=True) as db:\n        rows=db.execute(\'select id,tag,protocol,port,settings,stream_settings from inbounds order by id\').fetchall()\n        peers=db.execute(\'select id,email,wg_allowed_ips,enable,wg_public_key,wg_keep_alive from clients order by id\').fetchall()\n    return hashlib.sha256(repr((rows,peers)).encode()).hexdigest()\ndef service_state():\n    return {name:output(\'systemctl\',\'show\',name,\'-p\',\'MainPID\',\'-p\',\'ActiveState\') for name in [\'x-ui\',\'amnezia-native32\',\'amnezia-legacy-kernel-guard\']}\nwith sqlite3.connect(\'file:/etc/x-ui/x-ui.db?mode=ro\',uri=True) as db:\n    kernel_peers=set(output(\'awg\',\'show\',\'xui-awg1\',\'peers\').split())\n    for name,ip in TARGETS.items():\n        rows=db.execute(\'select wg_allowed_ips,enable,wg_public_key from clients where email=?\',(name,)).fetchall()\n        assert len(rows)==1 and rows[0][0]==ip+\'/32\' and rows[0][1]==1 and rows[0][2] in kernel_peers,name\nassert command([\'nft\',\'list\',\'table\',\'inet\',TABLE],False).returncode!=0,\'A bypass trial already exists\'\nold_rules=json.loads(output(\'ip\',\'-j\',\'-4\',\'rule\'))\nassert not any(int(rule.get(\'priority\',-1)) in PRIORITIES for rule in old_rules),\'Trial priorities occupied\'\nassert not command([\'ip\',\'-4\',\'route\',\'show\',\'table\',ROUTE_TABLE],False).stdout.strip(),\'Trial route table occupied\'\nall_firewall=output(\'nft\',\'list\',\'ruleset\')\nassert not re.search(r\'\\b(?:ct|meta) mark\\b\',all_firewall),\'Existing marking needs review before allocating a mark\'\nwan_route=json.loads(output(\'ip\',\'-j\',\'-4\',\'route\',\'get\',\'1.1.1.1\'))[0]\nwan,gateway=wan_route[\'dev\'],wan_route[\'gateway\']\nassert re.fullmatch(\'[A-Za-z0-9_.:-]{1,15}\',wan) and not wan.startswith((\'lo\',\'wg\',\'awg\',\'xui\',\'tun\'))\nipaddress.IPv4Address(gateway)\nguard=json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'))\nold_guard=rules(guard)\nposition=anchor(guard)\ntg=command([\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'awg_tg_client31_trial\'],False)\ntg_signatures=[rule_signature(rule) for rule in rules(json.loads(tg.stdout))] if tg.returncode==0 else None\nbefore={\'customers\':customer_hash(),\'services\':service_state(),\'main_routes\':output(\'ip\',\'-4\',\'route\',\'show\',\'table\',\'main\'),\n \'guard\':[rule_signature(rule) for rule in old_guard],\'telegram_trial\':tg_signatures}\n(root/\'before.json\').write_text(json.dumps(before,indent=2))\n(root/\'guard-before.nft\').write_text(output(\'nft\',\'-a\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'))\n(root/\'rules-before.json\').write_text(json.dumps(old_rules,indent=2))\nconfig=nft_config(source[\'ipv4_cidrs\'],wan,position)\npath=root/\'trial.nft\';path.write_text(config)\ncommand([\'nft\',\'-c\',\'-f\',str(path)])\nstamp=datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\ntimer=\'awg-ru3-rollback-\'+stamp\ndeadline=datetime.now(timezone.utc)+timedelta(minutes=30)\nstate={\'targets\':TARGETS,\'wan\':wan,\'gateway\':gateway,\'table\':TABLE,\'route_table\':ROUTE_TABLE,\n \'mark\':MARK,\'mask\':MASK,\'timer\':timer,\'rollback_deadline_utc\':deadline.isoformat(),\'source_commit\':source[\'source_commit\'],\n \'source_sha256\':source[\'source_sha256\'],\'ipv4_cidrs\':len(source[\'ipv4_cidrs\']),\'runtime_only\':True,\'new_connections_only\':True}\n(root/\'state.json\').write_text(json.dumps(state,indent=2))\nrollback=root/\'rollback.py\'\nmanual=root/\'manual-rollback.sh\'\nmanual.write_text(\'#!/bin/sh\\nset -eu\\n/usr/bin/python3 \'+str(rollback)+\'\\n\');manual.chmod(0o700)\ncommand([\'systemd-run\',\'--unit=\'+timer,\'--on-active=30m\',\'--timer-property=AccuracySec=1s\',\'/usr/bin/python3\',str(rollback)])\ntry:\n    for args in routing_commands(wan,gateway):command(args)\n    command([\'nft\',\'-f\',str(path)])\n    after_guard=rules(json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\')))\n    added=[rule for rule in after_guard if rule.get(\'comment\',\'\').startswith(PREFIX)]\n    assert len(added)==2\n    for original in before[\'guard\']:\n        matches=[rule for rule in after_guard if rule[\'handle\']==original[\'handle\']]\n        assert len(matches)==1 and rule_signature(matches[0])==original,\'Original guard rule changed\'\n    if tg_signatures is not None:\n        current=[rule_signature(rule) for rule in rules(json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'awg_tg_client31_trial\')))]\n        assert current==tg_signatures,\'Existing Telegram MSS trial changed\'\n    route_checks=[]\n    for ip in [*TARGETS.values(),UNSELECTED]:\n        for destination in [\'77.88.55.80\',\'1.1.1.1\',\'149.154.167.50\']:\n            direct=ip in TARGETS.values() and is_ru(destination)\n            args=[\'ip\',\'-4\',\'route\',\'get\',destination,\'from\',ip,\'iif\',\'xui-awg1\',\'mark\',MARK if direct else \'0\']\n            result=output(*args)\n            assert (\'dev \'+wan+\' table \'+ROUTE_TABLE in result) if direct else (\'dev awg32 table 51832\' in result),result\n            route_checks.append({\'source\':ip,\'destination\':destination,\'egress\':wan if direct else \'awg32\'})\n    assert customer_hash()==before[\'customers\'],\'Customer configuration changed\'\n    assert service_state()==before[\'services\'],\'Production service state changed\'\n    assert output(\'ip\',\'-4\',\'route\',\'show\',\'table\',\'main\')==before[\'main_routes\'],\'Main routing changed\'\n    report={**state,\'installed_utc\':datetime.now(timezone.utc).isoformat(),\'rollback_script\':str(manual),\n      \'customers_unchanged\':True,\'production_services_unchanged\':True,\'original_guard_unchanged\':True,\n      \'telegram_mss_trial_unchanged\':True,\'namespace_tests_passed\':simulation[\'namespace_tests\'],\'route_checks\':route_checks}\n    (root/\'verified.json\').write_text(json.dumps(report,indent=2))\n    print(json.dumps({k:v for k,v in report.items() if k!=\'route_checks\'}),flush=True)\nexcept BaseException:\n    result=subprocess.run([\'/usr/bin/python3\',str(rollback)],capture_output=True,text=True)\n    (root/\'apply-failure-rollback.txt\').write_text(result.stdout+result.stderr)\n    if result.returncode:raise RuntimeError(\'Apply failed and rollback needs review: \'+str(root))\n    raise\n', 'rollback.py': '"""Idempotently remove only the three-peer trial, preserving other firewall/routing state."""\nimport json,subprocess,sys,time\nfrom pathlib import Path\nfrom ru_bypass_common import TABLE,nft_cleanup,cleanup_commands\n\nroot=Path(__file__).resolve().parent\nstate=json.loads((root/\'state.json\').read_text())\ndef run(args,check=False):\n    result=subprocess.run(args,capture_output=True,text=True)\n    if check and result.returncode:raise RuntimeError(result.stderr.strip() or \'Trial rollback command failed\')\n    return result\nguard=run([\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'])\ndocument=json.loads(guard.stdout) if guard.returncode==0 else {\'nftables\':[]}\nexists=run([\'nft\',\'list\',\'table\',\'inet\',TABLE]).returncode==0\ntext=nft_cleanup(document,exists)\nif text:\n    path=root/\'rollback.nft\';path.write_text(text)\n    run([\'nft\',\'-c\',\'-f\',str(path)],check=True)\n    run([\'nft\',\'-f\',str(path)],check=True)\nfor command in cleanup_commands(state[\'wan\'],state[\'gateway\']):run(command)\n(root/\'rolled-back.json\').write_text(json.dumps({\'utc_epoch\':int(time.time()),\'removed_trial_only\':True},indent=2))\nprint(\'RU bypass trial removed. Original AWG routing restored; customer configuration and other trials retained.\')\n', 'control.py': '"""Manual on/off for selected RU bypass peers. Runtime only; never touches the customer DB."""\nimport argparse\nfrom datetime import datetime, timezone\nimport fcntl\nimport json\nimport os\nfrom pathlib import Path\nimport shutil\nimport subprocess\nfrom ru_bypass_common import TARGETS, TABLE, ROUTE_TABLE, MARK, MASK, PRIORITIES\n\nBASE=Path(__file__).resolve().parent\nPOINTER=BASE/\'controller-current.json\'\n\ndef run(*args,check=True):\n    result=subprocess.run(args,capture_output=True,text=True)\n    if check and result.returncode:raise RuntimeError(result.stderr.strip() or result.stdout.strip() or \'Command failed\')\n    return result\n\ndef current():\n    if not POINTER.exists():return None,None\n    root=Path(json.loads(POINTER.read_text())[\'root\'])\n    assert root.parent==BASE/\'runs\',\'Invalid controller state path\'\n    state=json.loads((root/\'state.json\').read_text())\n    assert state[\'targets\']==TARGETS and state[\'table\']==TABLE,\'Unexpected peer scope\'\n    return root,state\n\ndef active():return run(\'nft\',\'list\',\'table\',\'inet\',TABLE,check=False).returncode==0\n\ndef stop_timer(state):\n    if not state:return\n    timer=state[\'timer\']\n    assert timer.startswith(\'awg-ru3-rollback-\') and \'/\' not in timer\n    run(\'systemctl\',\'stop\',timer+\'.timer\',check=False)\n    if run(\'systemctl\',\'is-active\',timer+\'.service\',check=False).stdout.strip() in (\'active\',\'activating\',\'deactivating\'):\n        raise RuntimeError(\'Automatic rollback is running. Wait a few seconds and retry.\')\n    assert run(\'systemctl\',\'is-active\',timer+\'.timer\',check=False).stdout.strip()!=\'active\',\'Could not stop rollback timer\'\n\ndef verify_active(root,state):\n    assert root and state,\'An unmanaged bypass is active; refusing to replace it\'\n    assert not (root/\'rolled-back.json\').exists(),\'Unexpected firewall state after rollback\'\n    assert (root/\'verified.json\').exists(),\'Original apply verification missing\'\n    table=json.loads(run(\'nft\',\'-j\',\'list\',\'table\',\'inet\',TABLE).stdout)\n    sets=[item[\'set\'] for item in table[\'nftables\'] if \'set\' in item and item[\'set\'][\'name\']==\'peers4\']\n    assert len(sets)==1 and set(sets[0][\'elem\'])==set(TARGETS.values()),\'Unexpected peer set\'\n    rules=json.loads(run(\'ip\',\'-j\',\'-4\',\'rule\').stdout)\n    found=[r for r in rules if r.get(\'priority\') in PRIORITIES]\n    assert len(found)==2 and all(r.get(\'src\')==\'10.8.0.0\' and r.get(\'srclen\')==24 and r.get(\'fwmark\')==MARK and r.get(\'fwmask\')==MASK for r in found),\'Unexpected policy rules\'\n    assert any(str(r.get(\'table\'))==ROUTE_TABLE for r in found) and any(r.get(\'action\')==\'unreachable\' for r in found),\'Incomplete policy rules\'\n    guard=json.loads(run(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\').stdout)\n    comments=[item[\'rule\'].get(\'comment\') for item in guard[\'nftables\'] if \'rule\' in item and item[\'rule\'].get(\'comment\',\'\').startswith(\'awg-ru3-trial:\')]\n    assert sorted(comments)==[\'awg-ru3-trial:allow-out\',\'awg-ru3-trial:allow-return\'],\'Incomplete forwarding exceptions\'\n\ndef main():\n    parser=argparse.ArgumentParser(description=\'Russian IPv4 bypass for selected AWG peers, runtime only.\')\n    parser.add_argument(\'action\',choices=[\'on\',\'off\',\'status\'])\n    args=parser.parse_args()\n    assert os.geteuid()==0,\'Run as root on the relay\'\n    os.umask(0o077)\n    with (BASE/\'controller.lock\').open(\'a\') as lock:\n        fcntl.flock(lock,fcntl.LOCK_EX)\n        root,state=current()\n        enabled=active()\n        if enabled:verify_active(root,state)\n        if args.action==\'status\':\n            print(\'ON: Russian IPv4 goes directly through relay.\' if enabled else \'OFF: all destinations use the existing foreign exit.\')\n            print(\'Selected peers: \'+\', \'.join(name+\' (\'+ip+\')\' for name,ip in TARGETS.items()))\n            timer=state and run(\'systemctl\',\'is-active\',state[\'timer\']+\'.timer\',check=False).stdout.strip()==\'active\'\n            print(\'Automatic rollback: \'+state[\'rollback_deadline_utc\'] if enabled and timer else \'No active automatic rollback timer.\')\n            print(\'Runtime only: reboot removes the bypass. Domains/DNS and other customers are unchanged.\')\n            return\n        if args.action==\'off\':\n            stop_timer(state)\n            if state:print(run(\'/usr/bin/python3\',str(root/\'rollback.py\')).stdout.strip())\n            assert not active(),\'Bypass table remains after rollback\'\n            print(\'OFF. Reconnect the selected VPNs/reopen apps to replace existing connections.\')\n            return\n        if not enabled:\n            stop_timer(state)\n            newroot=BASE/\'runs\'/datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\n            newroot.mkdir(parents=True,mode=0o700)\n            for name in [\'ru_bypass_common.py\',\'config.json\',\'apply.py\',\'rollback.py\',\'ru-ipv4.json\',\'simulation-report.json\']:\n                shutil.copyfile(BASE/name,newroot/name)\n            result=run(\'/usr/bin/python3\',str(newroot/\'apply.py\'),check=False)\n            (newroot/\'controller-apply.log\').write_text(result.stdout+result.stderr)\n            if result.returncode:raise RuntimeError(\'Enable failed; apply has automatic rollback protection. See \'+str(newroot/\'controller-apply.log\'))\n            root=newroot;state=json.loads((root/\'state.json\').read_text())\n            temporary=POINTER.with_suffix(\'.tmp\')\n            temporary.write_text(json.dumps({\'root\':str(root)}));temporary.replace(POINTER)\n        verify_active(root,state)\n        stop_timer(state)\n        assert active() and not (root/\'rolled-back.json\').exists(),\'Rollback occurred; run on again\'\n        (root/\'manual-mode.json\').write_text(json.dumps({\'on_utc\':datetime.now(timezone.utc).isoformat(),\'automatic_expiry\':False}))\n        print(\'ON for the selected peers. Russian IPv4: relay; all other IPs: foreign exit.\')\n        print(\'No automatic expiry. Runtime only: reboot removes the bypass. Use ru-bypass off to disable.\')\n\nif __name__==\'__main__\':\n    try:main()\n    except (AssertionError,RuntimeError) as error:raise SystemExit(\'ERROR: \'+str(error))\n'}
"""Installer entry point embedded with the tested networking modules in ru-bypass.sh."""
import argparse
import fcntl
import hashlib
import ipaddress
import json
import os
from pathlib import Path
import re
import sqlite3
import subprocess
import sys
import urllib.request

BASE=Path('/root/amnezia-relay-deploy/ru-bypass')
COMMAND=Path('/usr/local/sbin/ru-bypass')
GEO_COMMIT='eace600e4e2d6708de3948b047ff9ff7bc5b5b11'
GEO_SHA='779e867ddeec1aca1e9501cc8cfe45f9c5d77531512a36c58d51e949da49adde'

def main():
    parser=argparse.ArgumentParser(description='Install Russian IPv4 bypass for selected existing kernel AWG peers. No boot persistence.')
    parser.add_argument('action',nargs='?',default='install',choices=['install','on','off','status'])
    parser.add_argument('--clients',help='Comma-separated exact LucX customer names; local only')
    args=parser.parse_args()
    assert os.geteuid()==0,'Run as root on the relay, not the exit'
    os.umask(0o077)
    wrapper='#!/bin/sh\nexec /usr/bin/python3 '+str(BASE/'control.py')+' "$@"\n'
    existing=COMMAND.read_text() if COMMAND.exists() and not COMMAND.is_symlink() else None
    legacy=re.fullmatch(r'#!/bin/sh\nexec /usr/bin/python3 (/root/amnezia-relay-deploy/ru-bypass3-[0-9TZ]+/control.py) "\$@"\n',existing or '')
    assert not COMMAND.is_symlink(),'Refusing to overwrite a symlink'
    assert existing is None or existing==wrapper or legacy,'Another ru-bypass command already exists'
    if args.action in ('off','status'):
        assert existing,'Not installed. Run install --clients first.'
        subprocess.run([str(COMMAND),args.action],check=True)
        return
    names=[name.strip() for name in args.clients.split(',')] if args.clients else []
    if args.action=='install' and not names:
        with open('/dev/tty','r+') as terminal:
            terminal.write('Exact LucX names, comma-separated (selected clients only): ');terminal.flush()
            names=[name.strip() for name in terminal.readline().strip().split(',')]
    if args.action=='on' and not names:
        assert existing,'Not installed. Run install --clients first.'
        subprocess.run([str(COMMAND),'on'],check=True)
        return
    assert names and all(names) and len(set(names))==len(names),'Provide distinct customer names'
    assert len(names)<=20,'This installer is for a small selected group (maximum20 peers)'
    targets={}
    with sqlite3.connect('file:/etc/x-ui/x-ui.db?mode=ro',uri=True) as db:
        for name in names:
            rows=db.execute('select wg_allowed_ips,enable from clients where email=?',(name,)).fetchall()
            assert len(rows)==1 and rows[0][1]==1,'Customer missing, ambiguous or disabled: '+name
            address=ipaddress.ip_interface(rows[0][0])
            assert address.version==4 and address.network.prefixlen==32 and address.ip in ipaddress.ip_network('10.8.0.0/24') and int(address.ip.packed[-1]) not in (0,1,255),'Unsupported AWG address: '+name
            targets[name]=str(address.ip)
    assert len(set(targets.values()))==len(targets),'Customer addresses overlap'
    if legacy:
        oldroot=Path(legacy.group(1)).parent
        state=json.loads((oldroot/'state.json').read_text())
        pointer=oldroot/'controller-current.json'
        if pointer.exists():state=json.loads((Path(json.loads(pointer.read_text())['root'])/'state.json').read_text())
        assert state['targets']==targets,'Existing trial has a different scope; do not replace it live'
        print('Existing compatible three-peer installation retained.',flush=True)
        subprocess.run([str(COMMAND),'on'],check=True)
        return
    BASE.mkdir(parents=True,exist_ok=True,mode=0o700)
    with (BASE/'install.lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX)
        config=BASE/'config.json'
        value={'targets':targets}
        if config.exists():
            assert json.loads(config.read_text())==value,'Installed peer scope differs. Existing configuration was retained.'
            for name,content in FILES.items():
                assert (BASE/name).read_text()==content,'Installed code differs; inspect before replacing'
        else:
            assert not any((BASE/name).exists() for name in FILES),'Incomplete existing installation; inspect the folder'
            # Validate and download everything before installing a runnable command.
            url=f'https://raw.githubusercontent.com/Loyalsoldier/geoip/{GEO_COMMIT}/text/ru.txt'
            request=urllib.request.Request(url,headers={'User-Agent':'awg-ru-bypass-installer'})
            with urllib.request.urlopen(request,timeout=45) as response:data=response.read(2*1024*1024)
            assert hashlib.sha256(data).hexdigest()==GEO_SHA,'GeoIP source checksum mismatch'
            networks=[ipaddress.ip_network(line.strip(),strict=True) for line in data.decode().splitlines() if line.strip()]
            v4=list(ipaddress.collapse_addresses(n for n in networks if n.version==4))
            assert 1000<len(v4)<100000 and all(n.is_global and n.prefixlen>=8 for n in v4),'Unexpected country networks'
            payload={'source_commit':GEO_COMMIT,'source_sha256':GEO_SHA,'ipv4_cidrs':[str(n) for n in v4]}
            for name,content in FILES.items():compile(content,name,'exec')
            config.write_text(json.dumps(value,indent=2))
            (BASE/'ru-ipv4.json').write_text(json.dumps(payload))
            for name,content in FILES.items():(BASE/name).write_text(content)
        print('Validating routing/NAT/rollback in isolated network namespaces...',flush=True)
        subprocess.run(['/usr/bin/python3',str(BASE/'simulate.py'),str(BASE)],check=True)
        COMMAND.write_text(wrapper);COMMAND.chmod(0o700)
    subprocess.run([str(COMMAND),'on'],check=True)
    print('Installed. Commands: ru-bypass on | ru-bypass off | ru-bypass status',flush=True)

if __name__=='__main__':
    try:main()
    except (AssertionError,RuntimeError,OSError,ValueError,sqlite3.Error,subprocess.CalledProcessError) as error:
        raise SystemExit('ERROR: '+str(error))

RU_BYPASS_PYTHON
